-- docs/research/final-independent-20261018/db-baseline.sql
begin read only; select jsonb_build_object('observed_at',clock_timestamp(),'read_only',current_setting('transaction_read_only'),'migrations',(select jsonb_agg(x) from (select version,name,encode(extensions.digest(convert_to(array_to_string(statements,''),'UTF8'),'sha256'),'hex') sha256 from supabase_migrations.schema_migrations where version in ('20261017200000','20261017200100','20261018120000','20261018120100') order by version)x),'counts',jsonb_build_object('qualification',(select count(*) from public.content_qualification),'release_approval',(select count(*) from public.content_release_approval),'release_revocation',(select count(*) from public.content_release_revocation),'annotation',(select count(*) from public.supply_current_annotation),'demand',(select count(*) from public.workspace_content_demand),'order',(select count(*) from public.factory_order),'delivery',(select count(*) from public.workspace_content_delivery),'delivery_attempt',(select count(*) from public.workspace_delivery_attempt)),'knowledge_columns',(select jsonb_agg(column_name order by ordinal_position) from information_schema.columns where table_schema='public' and table_name='knowledge_applications'),'privileges',(select jsonb_agg(x) from (select r as role, has_table_privilege(r,'public.workspace_delivery_attempt','INSERT') as binding_insert,has_table_privilege(r,'public.supply_current_annotation','SELECT') as annotation_select,has_function_privilege(r,'public.workspace_delivery_attempt_record(uuid,bigint,uuid)','EXECUTE') as bind_rpc from unnest(array['anon','authenticated','service_role']) r)x)) snapshot; commit;
